CREATE TABLE local_agents (id TEXT PRIMARY KEY NOT NULL,owner_id TEXT NOT NULL REFERENCES user(id) ON DELETE RESTRICT,name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,capabilities_json TEXT NOT NULL CHECK(json_valid(capabilities_json)),disk_free_bytes INTEGER NOT NULL DEFAULT 0 CHECK(disk_free_bytes>=0),last_seen_at TEXT,revoked_at TEXT,probe_version TEXT,revision INTEGER NOT NULL DEFAULT 1,mutation_token TEXT,created_at TEXT NOT NULL,UNIQUE(id,owner_id));
